from lib import *
LES = [
L("feyn", "F", "Feynman's trick", "Feynman's trick",
 [T("<b>Theorem (Leibniz integral rule).</b> Let $f$ and $\\dfrac{\\partial f}{\\partial t}$ be continuous on the rectangle $[a,b]\\times[c,d]$. Then $I(t)=\\displaystyle\\int_{a}^{b}f(x,t)\\,dx$ is differentiable on $[c,d]$ and $$I'(t)=\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx.$$",
    "<b>ทฤษฎีบท (กฎอินทิกรัลของไลบ์นิซ)</b> ให้ $f$ และ $\\dfrac{\\partial f}{\\partial t}$ ต่อเนื่องบนสี่เหลี่ยม $[a,b]\\times[c,d]$ แล้ว $I(t)=\\displaystyle\\int_{a}^{b}f(x,t)\\,dx$ หาอนุพันธ์ได้บน $[c,d]$ และ $$I'(t)=\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx$$"),
  T("<b>Improper integrals</b> (e.g. over $[0,\\infty)$, or with a singular endpoint): the same conclusion holds if there is $g$ with $\\displaystyle\\int g<\\infty$ and $\\left|\\frac{\\partial f}{\\partial t}(x,t)\\right|\\le g(x)$ for all $t$ in the interval (a consequence of the <b>dominated convergence theorem</b>, which we quote).",
    "<b>อินทิกรัลไม่ตรงแบบ</b> (เช่นบน $[0,\\infty)$ หรือมีจุดเอกฐานที่ปลาย): ข้อสรุปเดียวกันเป็นจริงถ้ามี $g$ ที่ $\\displaystyle\\int g<\\infty$ และ $\\left|\\frac{\\partial f}{\\partial t}(x,t)\\right|\\le g(x)$ ทุก $t$ ในช่วง (ผลจาก<b>ทฤษฎีบทการลู่เข้าแบบถูกครอบงำ</b> ซึ่งเราอ้างถึง)")],
 [S("Fix $t$ and $h\\neq0$ with $t+h\\in[c,d]$. For each $x$, the mean value theorem in the variable $t$ gives $\\theta=\\theta(x,h)\\in(0,1)$ with", "กำหนด $t$ และ $h\\neq0$ ที่ $t+h\\in[c,d]$ สำหรับแต่ละ $x$ ทฤษฎีบทค่าเฉลี่ยในตัวแปร $t$ ให้ $\\theta=\\theta(x,h)\\in(0,1)$ ที่", "\\frac{f(x,t+h)-f(x,t)}{h}=\\frac{\\partial f}{\\partial t}(x,t+\\theta h)."),
  S("$\\frac{\\partial f}{\\partial t}$ is continuous on a closed bounded rectangle, so it is <b>uniformly continuous</b>: for every $\\varepsilon>0$ there is $\\delta>0$ such that $|s-t|<\\delta$ implies, for <i>all</i> $x$,", "$\\frac{\\partial f}{\\partial t}$ ต่อเนื่องบนสี่เหลี่ยมปิดและมีขอบเขต จึง<b>ต่อเนื่องเอกรูป</b>: ทุก $\\varepsilon>0$ มี $\\delta>0$ ที่ $|s-t|<\\delta$ ทำให้ สำหรับ<i>ทุก</i> $x$", "\\left|\\frac{\\partial f}{\\partial t}(x,s)-\\frac{\\partial f}{\\partial t}(x,t)\\right|<\\varepsilon."),
  S("The difference quotient is continuous in $x$, so integrable. For $0<|h|<\\delta$ (so $|\\theta h|<\\delta$):", "ผลหารผลต่างต่อเนื่องใน $x$ จึงอินทิเกรตได้ สำหรับ $0<|h|<\\delta$ (ดังนั้น $|\\theta h|<\\delta$):", "\\left|\\frac{I(t+h)-I(t)}{h}-\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx\\right|\\le\\int_{a}^{b}\\left|\\frac{\\partial f}{\\partial t}(x,t+\\theta h)-\\frac{\\partial f}{\\partial t}(x,t)\\right|dx\\le\\varepsilon(b-a)."),
  S("$\\varepsilon$ was arbitrary, so the limit as $h\\to0$ exists and equals $\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx$. $\\blacksquare$", "$\\varepsilon$ เป็นค่าใดก็ได้ ลิมิตเมื่อ $h\\to0$ จึงมีค่าและเท่ากับ $\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx$ $\\blacksquare$"),
  S("<b>Method.</b> Put a parameter $t$ into the integral so that $\\frac{\\partial f}{\\partial t}$ is easy, find $I'(t)$, integrate in $t$, and fix the constant with an easy value of $t$ (check the conditions above).", "<b>วิธีใช้</b> ใส่พารามิเตอร์ $t$ ลงในอินทิกรัลให้ $\\frac{\\partial f}{\\partial t}$ ง่าย หา $I'(t)$ อินทิเกรตเทียบ $t$ แล้วหาค่าคงตัวจากค่า $t$ ที่ง่าย (ตรวจเงื่อนไขข้างต้น)")],
 [X(r"\int_{0}^{1}\frac{x^{2}-1}{\ln x}\,dx", "ln(3)", r"\ln3", "(x**2-1)/log(x)", ("d", "0", "1"), [r"I(t)=\int_{0}^{1}\frac{x^{t}-1}{\ln x}dx,\ \ \frac{\partial}{\partial t}\frac{x^{t}-1}{\ln x}=x^{t}", r"I'(t)=\int_{0}^{1}x^{t}dx=\frac{1}{t+1},\ I(0)=0", r"I(t)=\ln(t+1),\ I(2)=\ln3"]),
  X(r"\int_{0}^{1}x^{2}\ln x\,dx", "-1/9", r"-\frac19", "x**2*log(x)", ("d", "0", "1"), [r"\int_{0}^{1}x^{t}dx=\frac{1}{t+1}\ (t>-1)", r"\frac{d}{dt}:\ \int_{0}^{1}x^{t}\ln x\,dx=-\frac{1}{(t+1)^{2}}", r"t=2:\ -\frac19"])],
 [P(r"\int_{0}^{1}x^{3}\ln x\,dx", "-1/16", r"-\frac{1}{16}", "x**3*log(x)", ("d", "0", "1"), [r"\int_{0}^{1}x^{t}\ln x\,dx=-\frac{1}{(t+1)^{2}}", r"t=3:\ -\frac{1}{16}"], "Differentiate $\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}$ with respect to $t$.", "หาอนุพันธ์ $\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}$ เทียบ $t$"),
  P(r"\int_{0}^{1}\frac{x^{5}-1}{\ln x}\,dx", "ln(6)", r"\ln6", "(x**5-1)/log(x)", ("d", "0", "1"), [r"I(t)=\ln(t+1)", r"I(5)=\ln6"], "Same $I(t)$ as the first example.", "ใช้ $I(t)$ เดียวกับตัวอย่างแรก"),
  P(r"\int_{0}^{\infty}xe^{-3x}\,dx", "1/9", r"\frac19", "x*exp(-3*x)", ("d", "0", "inf"), [r"\int_{0}^{\infty}e^{-tx}dx=\frac1t\ (t>0)", r"-\frac{d}{dt}:\ \int_{0}^{\infty}xe^{-tx}dx=\frac{1}{t^{2}},\ t=3"], "Start from $\\int_{0}^{\\infty}e^{-tx}dx=\\frac1t$.", "เริ่มจาก $\\int_{0}^{\\infty}e^{-tx}dx=\\frac1t$"),
  P(r"\int_{0}^{1}x^{2}(\ln x)^{2}\,dx", "2/27", r"\frac{2}{27}", "x**2*log(x)**2", ("d", "0", "1"), [r"\frac{d^{2}}{dt^{2}}\frac{1}{t+1}=\frac{2}{(t+1)^{3}}=\int_{0}^{1}x^{t}(\ln x)^{2}dx", r"t=2:\ \frac{2}{27}"], "Differentiate twice.", "หาอนุพันธ์สองครั้ง"),
  P(r"\int_{0}^{\frac\pi2}\ln\left(4\cos^{2}x+\sin^{2}x\right)dx", "pi*ln(3/2)", r"\pi\ln\frac32", "log(4*cos(x)**2+sin(x)**2)", ("d", "0", "pi/2"), [r"I(a)=\int_{0}^{\frac\pi2}\ln\left(a^{2}\cos^{2}x+\sin^{2}x\right)dx,\ a>0", r"I'(a)=\int_{0}^{\frac\pi2}\frac{2a\cos^{2}x}{a^{2}\cos^{2}x+\sin^{2}x}dx=\frac{\pi}{a+1}\ \ (t=\tan x)", r"I(1)=0\Rightarrow I(a)=\pi\ln\frac{a+1}{2},\ \ I(2)=\pi\ln\frac32"], "Put $a^{2}$ in front of $\\cos^{2}x$; $I(1)=0$.", "ใส่ $a^{2}$ หน้า $\\cos^{2}x$ และ $I(1)=0$")]),

L("series", "F", "Integrating a series term by term", "อินทิเกรตอนุกรมทีละพจน์",
 [T("<b>Theorem.</b> (i) If each $f_n$ is continuous on $[a,b]$ and $\\sum f_n$ converges <b>uniformly</b> on $[a,b]$, then $\\displaystyle\\int_{a}^{b}\\sum_{n}f_n=\\sum_{n}\\int_{a}^{b}f_n$. (ii) If $f_n\\ge0$ on $(a,b)$ (bounded or not), then $\\displaystyle\\int_{a}^{b}\\sum f_n=\\sum\\int_{a}^{b}f_n$, both sides possibly $+\\infty$ (<b>monotone convergence theorem</b>, quoted).",
    "<b>ทฤษฎีบท</b> (i) ถ้า $f_n$ แต่ละตัวต่อเนื่องบน $[a,b]$ และ $\\sum f_n$ ลู่เข้า<b>เอกรูป</b>บน $[a,b]$ แล้ว $\\displaystyle\\int_{a}^{b}\\sum_{n}f_n=\\sum_{n}\\int_{a}^{b}f_n$ (ii) ถ้า $f_n\\ge0$ บน $(a,b)$ (มีขอบเขตหรือไม่ก็ได้) แล้ว $\\displaystyle\\int_{a}^{b}\\sum f_n=\\sum\\int_{a}^{b}f_n$ ทั้งสองข้างอาจเป็น $+\\infty$ (<b>ทฤษฎีบทการลู่เข้าแบบทางเดียว</b> ซึ่งเราอ้างถึง)"),
  T("We also quote the <b>Basel result</b> (Euler): $\\displaystyle\\sum_{n=1}^{\\infty}\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}$ (one proof uses Fourier series), and the <b>geometric series</b> $\\dfrac{1}{1-x}=\\sum_{n\\ge0}x^{n}$ for $|x|<1$.",
    "เราอ้างถึง<b>ผลของบาเซิล</b> (ออยเลอร์): $\\displaystyle\\sum_{n=1}^{\\infty}\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}$ (พิสูจน์ได้ด้วยอนุกรมฟูริเยร์) และ<b>อนุกรมเรขาคณิต</b> $\\dfrac{1}{1-x}=\\sum_{n\\ge0}x^{n}$ เมื่อ $|x|<1$")],
 [S("(i) Let $S=\\sum f_n$ and $S_N=\\sum_{n\\le N}f_n$. A uniform limit of continuous functions is continuous, so $S$ is integrable, and by linearity $\\int S_N=\\sum_{n\\le N}\\int f_n$.", "(i) ให้ $S=\\sum f_n$ และ $S_N=\\sum_{n\\le N}f_n$ ลิมิตเอกรูปของฟังก์ชันต่อเนื่องเป็นฟังก์ชันต่อเนื่อง $S$ จึงอินทิเกรตได้ และจากความเป็นเชิงเส้น $\\int S_N=\\sum_{n\\le N}\\int f_n$"),
  S("Uniform convergence means $\\sup_{[a,b]}|S-S_N|\\to0$, so", "การลู่เข้าเอกรูปหมายถึง $\\sup_{[a,b]}|S-S_N|\\to0$ ดังนั้น", "\\left|\\int_{a}^{b}S-\\sum_{n\\le N}\\int_{a}^{b}f_n\\right|=\\left|\\int_{a}^{b}(S-S_N)\\right|\\le(b-a)\\sup_{[a,b]}|S-S_N|\\to0."),
  S("(ii) is the monotone convergence theorem applied to the increasing partial sums $S_N\\ge0$; we quote it.", "(ii) คือทฤษฎีบทการลู่เข้าแบบทางเดียวกับผลบวกย่อย $S_N\\ge0$ ที่เพิ่มขึ้น เราอ้างถึง"),
  S("<b>Consequence.</b> From Basel, splitting even and odd $n$:", "<b>ผลที่ตามมา</b> จากผลของบาเซิล แยก $n$ คู่และคี่:", "\\sum_{n\\ge1}\\frac{(-1)^{n-1}}{n^{2}}=\\sum\\frac{1}{n^{2}}-2\\sum\\frac{1}{(2n)^{2}}=\\left(1-\\tfrac12\\right)\\frac{\\pi^{2}}{6}=\\frac{\\pi^{2}}{12}.\\ \\blacksquare"),
  S("<b>Note on alternating series.</b> When the terms change sign on an open interval, use (i) on $[0,r]$ with $r<1$ and let $r\\to1^{-}$, or quote dominated convergence.", "<b>หมายเหตุเรื่องอนุกรมสลับ</b> เมื่อพจน์เปลี่ยนเครื่องหมายบนช่วงเปิด ใช้ (i) บน $[0,r]$ โดย $r<1$ แล้วให้ $r\\to1^{-}$ หรืออ้างทฤษฎีบทการลู่เข้าแบบถูกครอบงำ")],
 [X(r"\int_{0}^{1}\frac{\ln(1-x)}{x}\,dx", "-pi^2/6", r"-\frac{\pi^{2}}{6}", "log(1-x)/x", ("d", "0", "1"), [r"-\frac{\ln(1-x)}{x}=\sum_{n\ge1}\frac{x^{n-1}}{n}\ \ (\text{terms}\ge0:\text{ theorem (ii)})", r"\int_{0}^{1}=\sum\frac{1}{n}\cdot\frac{1}{n}=\frac{\pi^{2}}{6}", r"\text{so the integral is }-\frac{\pi^{2}}{6}"]),
  X(r"\int_{0}^{\infty}\frac{x}{e^{x}-1}\,dx", "pi^2/6", r"\frac{\pi^{2}}{6}", "x/(exp(x)-1)", ("d", "0", "inf"), [r"\frac{x}{e^{x}-1}=\sum_{n\ge1}xe^{-nx}\ (x>0,\ \text{terms}\ge0)", r"\int_{0}^{\infty}xe^{-nx}dx=\frac{1}{n^{2}}", r"\sum\frac{1}{n^{2}}=\frac{\pi^{2}}{6}"])],
 [P(r"\int_{0}^{1}\frac{\ln\left(1-x^{2}\right)}{x}\,dx", "-pi^2/12", r"-\frac{\pi^{2}}{12}", "log(1-x**2)/x", ("d", "0", "1"), [r"-\frac{\ln(1-x^{2})}{x}=\sum_{n\ge1}\frac{x^{2n-1}}{n}", r"\int_{0}^{1}=\sum\frac{1}{n\cdot2n}=\frac12\cdot\frac{\pi^{2}}{6}", r"I=-\frac{\pi^{2}}{12}"], "$\\ln(1-u)=-\\sum\\frac{u^{n}}{n}$ with $u=x^{2}$.", "$\\ln(1-u)=-\\sum\\frac{u^{n}}{n}$ โดย $u=x^{2}$"),
  P(r"\int_{0}^{\infty}\frac{x}{e^{2x}-1}\,dx", "pi^2/24", r"\frac{\pi^{2}}{24}", "x/(exp(2*x)-1)", ("d", "0", "inf"), [r"u=2x:\ \frac14\int_{0}^{\infty}\frac{u}{e^{u}-1}du", r"=\frac14\cdot\frac{\pi^{2}}{6}=\frac{\pi^{2}}{24}"], "Substitute $u=2x$ and use the second example.", "แทน $u=2x$ แล้วใช้ตัวอย่างที่สอง"),
  P(r"\int_{0}^{1}\frac{\ln x}{1-x}\,dx", "-pi^2/6", r"-\frac{\pi^{2}}{6}", "log(x)/(1-x)", ("d", "0", "1"), [r"\frac{-\ln x}{1-x}=\sum_{n\ge0}(-\ln x)x^{n}\ (\text{terms}\ge0)", r"\int_{0}^{1}x^{n}(-\ln x)\,dx=\frac{1}{(n+1)^{2}}", r"I=-\frac{\pi^{2}}{6}"], "Expand $\\frac{1}{1-x}$; $\\int_{0}^{1}x^{n}\\ln x\\,dx=-\\frac{1}{(n+1)^{2}}$.", "กระจาย $\\frac{1}{1-x}$ และ $\\int_{0}^{1}x^{n}\\ln x\\,dx=-\\frac{1}{(n+1)^{2}}$"),
  P(r"\int_{0}^{\infty}\frac{x}{e^{x}+1}\,dx", "pi^2/12", r"\frac{\pi^{2}}{12}", "x/(exp(x)+1)", ("d", "0", "inf"), [r"\frac{x}{e^{x}+1}=\sum_{n\ge1}(-1)^{n-1}xe^{-nx}", r"\sum\frac{(-1)^{n-1}}{n^{2}}=\frac{\pi^{2}}{12}"], "Alternating version of the second example.", "แบบสลับเครื่องหมายของตัวอย่างที่สอง"),
  P(r"\int_{0}^{\infty}\ln\left(1+e^{-x}\right)dx", "pi^2/12", r"\frac{\pi^{2}}{12}", "log(1+exp(-x))", ("d", "0", "inf"), [r"\ln(1+u)=\sum_{n\ge1}\frac{(-1)^{n-1}u^{n}}{n},\ u=e^{-x}", r"\int_{0}^{\infty}e^{-nx}dx=\frac1n:\ \sum\frac{(-1)^{n-1}}{n^{2}}=\frac{\pi^{2}}{12}"], "Expand $\\ln(1+u)$ with $u=e^{-x}$.", "กระจาย $\\ln(1+u)$ โดย $u=e^{-x}$")]),

L("frul", "F", "Frullani's integral", "อินทิกรัลของฟรุลลานี",
 [T("<b>Theorem (Frullani).</b> Let $f$ be continuous on $[0,\\infty)$ with a finite limit $f(\\infty)=\\displaystyle\\lim_{x\\to\\infty}f(x)$, and let $a,b>0$. Then $$\\int_{0}^{\\infty}\\frac{f(ax)-f(bx)}{x}\\,dx=\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba.$$",
    "<b>ทฤษฎีบท (ฟรุลลานี)</b> ให้ $f$ ต่อเนื่องบน $[0,\\infty)$ และมีลิมิตจำกัด $f(\\infty)=\\displaystyle\\lim_{x\\to\\infty}f(x)$ และ $a,b>0$ แล้ว $$\\int_{0}^{\\infty}\\frac{f(ax)-f(bx)}{x}\\,dx=\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba$$")],
 [S("Take $0<\\varepsilon<R$. Substitute $u=ax$ in the first part and $u=bx$ in the second (each $\\frac{dx}{x}=\\frac{du}{u}$):", "ให้ $0<\\varepsilon<R$ แทน $u=ax$ ในส่วนแรกและ $u=bx$ ในส่วนที่สอง (ทั้งคู่ $\\frac{dx}{x}=\\frac{du}{u}$):", "\\int_{\\varepsilon}^{R}\\frac{f(ax)-f(bx)}{x}\\,dx=\\int_{a\\varepsilon}^{aR}\\frac{f(u)}{u}\\,du-\\int_{b\\varepsilon}^{bR}\\frac{f(u)}{u}\\,du."),
  S("The overlapping part cancels, leaving", "ส่วนที่ซ้อนทับกันหักล้างกัน เหลือ", "=\\int_{a\\varepsilon}^{b\\varepsilon}\\frac{f(u)}{u}\\,du-\\int_{aR}^{bR}\\frac{f(u)}{u}\\,du."),
  S("Weighted mean value theorem for integrals (weight $\\frac1u>0$; lesson 12): there are $c_\\varepsilon$ between $a\\varepsilon$ and $b\\varepsilon$, and $C_R$ between $aR$ and $bR$, with", "ทฤษฎีบทค่าเฉลี่ยถ่วงน้ำหนัก (น้ำหนัก $\\frac1u>0$; บทที่ 12): มี $c_\\varepsilon$ ระหว่าง $a\\varepsilon$ กับ $b\\varepsilon$ และ $C_R$ ระหว่าง $aR$ กับ $bR$ ที่", "\\int_{a\\varepsilon}^{b\\varepsilon}\\frac{f(u)}{u}du=f(c_\\varepsilon)\\ln\\frac ba,\\qquad \\int_{aR}^{bR}\\frac{f(u)}{u}du=f(C_R)\\ln\\frac ba."),
  S("As $\\varepsilon\\to0^{+}$, $c_\\varepsilon\\to0$ so $f(c_\\varepsilon)\\to f(0)$ (continuity); as $R\\to\\infty$, $C_R\\to\\infty$ so $f(C_R)\\to f(\\infty)$. Both limits exist, so the improper integral converges to $\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba$. $\\blacksquare$", "เมื่อ $\\varepsilon\\to0^{+}$ จะได้ $c_\\varepsilon\\to0$ ดังนั้น $f(c_\\varepsilon)\\to f(0)$ (ความต่อเนื่อง) เมื่อ $R\\to\\infty$ จะได้ $C_R\\to\\infty$ ดังนั้น $f(C_R)\\to f(\\infty)$ ลิมิตทั้งสองมีค่า อินทิกรัลจึงลู่เข้าสู่ $\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba$ $\\blacksquare$")],
 [X(r"\int_{0}^{\infty}\frac{e^{-x}-e^{-3x}}{x}\,dx", "ln(3)", r"\ln3", "(exp(-x)-exp(-3*x))/x", ("d", "0", "inf"), [r"f=e^{-x},\ f(0)=1,\ f(\infty)=0,\ a=1,\ b=3", r"(1-0)\ln3=\ln3"]),
  X(r"\int_{0}^{\infty}\frac{\arctan3x-\arctan x}{x}\,dx", "pi/2*ln(3)", r"\frac\pi2\ln3", "(atan(3*x)-atan(x))/x", ("d", "0", "inf"), [r"f=\arctan,\ f(0)=0,\ f(\infty)=\tfrac\pi2,\ a=3,\ b=1", r"\left(0-\tfrac\pi2\right)\ln\tfrac13=\frac\pi2\ln3"])],
 [P(r"\int_{0}^{\infty}\frac{e^{-2x}-e^{-5x}}{x}\,dx", "ln(5/2)", r"\ln\frac52", "(exp(-2*x)-exp(-5*x))/x", ("d", "0", "inf"), [r"f=e^{-x},\ a=2,\ b=5:\ (1-0)\ln\frac52"], "$f(x)=e^{-x}$, $a=2$, $b=5$.", "$f(x)=e^{-x}$, $a=2$, $b=5$"),
  P(r"\int_{0}^{\infty}\frac{\arctan2x-\arctan x}{x}\,dx", "pi/2*ln(2)", r"\frac\pi2\ln2", "(atan(2*x)-atan(x))/x", ("d", "0", "inf"), [r"\left(0-\tfrac\pi2\right)\ln\tfrac12=\frac\pi2\ln2"], "Like the second example with $a=2$.", "เหมือนตัวอย่างที่สองโดย $a=2$"),
  P(r"\int_{0}^{\infty}\frac{1}{x}\left(\frac{1}{1+2x}-\frac{1}{1+3x}\right)dx", "ln(3/2)", r"\ln\frac32", "(1/(1+2*x)-1/(1+3*x))/x", ("d", "0", "inf"), [r"f(x)=\frac{1}{1+x},\ f(0)=1,\ f(\infty)=0", r"a=2,\ b=3:\ \ln\frac32"], "$f(x)=\\frac{1}{1+x}$.", "$f(x)=\\frac{1}{1+x}$"),
  P(r"\int_{0}^{\infty}\frac{e^{-x}-e^{-\frac x2}}{x}\,dx", "-ln(2)", r"-\ln2", "(exp(-x)-exp(-x/2))/x", ("d", "0", "inf"), [r"a=1,\ b=\tfrac12:\ (1-0)\ln\tfrac12=-\ln2"], "$b=\\frac12$, so $\\ln\\frac ba<0$.", "$b=\\frac12$ ดังนั้น $\\ln\\frac ba<0$"),
  P(r"\int_{0}^{\infty}\frac{\tanh3x-\tanh x}{x}\,dx", "ln(3)", r"\ln3", "(tanh(3*x)-tanh(x))/x", ("d", "0", "inf"), [r"f=\tanh,\ f(0)=0,\ f(\infty)=1,\ a=3,\ b=1", r"(0-1)\ln\tfrac13=\ln3"], "$\\tanh x\\to1$ as $x\\to\\infty$.", "$\\tanh x\\to1$ เมื่อ $x\\to\\infty$")]),

L("gauss", "F", "The Gaussian integral", "อินทิกรัลเกาส์เซียน",
 [T("<b>Theorem.</b> $$\\int_{-\\infty}^{\\infty}e^{-x^{2}}\\,dx=\\sqrt\\pi,\\qquad\\text{and for }a>0,\\ \\int_{-\\infty}^{\\infty}e^{-ax^{2}}\\,dx=\\sqrt{\\frac\\pi a}.$$",
    "<b>ทฤษฎีบท</b> $$\\int_{-\\infty}^{\\infty}e^{-x^{2}}\\,dx=\\sqrt\\pi\\qquad\\text{และสำหรับ }a>0,\\ \\int_{-\\infty}^{\\infty}e^{-ax^{2}}\\,dx=\\sqrt{\\frac\\pi a}$$"),
  T("We quote the <b>change of variables to polar coordinates</b> for double integrals: $\\iint_{D}g(x,y)\\,dx\\,dy=\\iint g(r\\cos\\theta,r\\sin\\theta)\\,r\\,dr\\,d\\theta$ for continuous $g$ on a bounded region $D$.", "เราอ้างถึง<b>การเปลี่ยนตัวแปรเป็นพิกัดเชิงขั้ว</b>สำหรับอินทิกรัลสองชั้น: $\\iint_{D}g(x,y)\\,dx\\,dy=\\iint g(r\\cos\\theta,r\\sin\\theta)\\,r\\,dr\\,d\\theta$ สำหรับ $g$ ต่อเนื่องบนบริเวณ $D$ ที่มีขอบเขต")],
 [S("<b>Convergence.</b> $0<e^{-x^{2}}\\le e^{-x}$ for $x\\ge1$ and $\\int_{1}^{\\infty}e^{-x}dx=e^{-1}$, so $I=\\int_{0}^{\\infty}e^{-x^{2}}dx$ converges (comparison test).", "<b>การลู่เข้า</b> $0<e^{-x^{2}}\\le e^{-x}$ เมื่อ $x\\ge1$ และ $\\int_{1}^{\\infty}e^{-x}dx=e^{-1}$ ดังนั้น $I=\\int_{0}^{\\infty}e^{-x^{2}}dx$ ลู่เข้า (การทดสอบโดยการเปรียบเทียบ)"),
  S("Let $I_R=\\int_{0}^{R}e^{-x^{2}}dx$. Over the square $S_R=[0,R]^{2}$ the integrand factorises:", "ให้ $I_R=\\int_{0}^{R}e^{-x^{2}}dx$ บนสี่เหลี่ยมจัตุรัส $S_R=[0,R]^{2}$ ฟังก์ชันแยกตัวประกอบได้:", "\\iint_{S_R}e^{-(x^{2}+y^{2})}\\,dx\\,dy=\\int_{0}^{R}e^{-x^{2}}dx\\int_{0}^{R}e^{-y^{2}}dy=I_R^{2}."),
  S("Let $D_R$ be the quarter disc of radius $R$ in the first quadrant. In polar coordinates,", "ให้ $D_R$ เป็นหนึ่งในสี่ของวงกลมรัศมี $R$ ในจตุภาคที่หนึ่ง ในพิกัดเชิงขั้ว", "\\iint_{D_R}e^{-(x^{2}+y^{2})}dx\\,dy=\\int_{0}^{\\frac\\pi2}\\int_{0}^{R}e^{-r^{2}}r\\,dr\\,d\\theta=\\frac\\pi4\\left(1-e^{-R^{2}}\\right)."),
  S("$D_R\\subset S_R\\subset D_{R\\sqrt2}$ and the integrand is positive, so", "$D_R\\subset S_R\\subset D_{R\\sqrt2}$ และฟังก์ชันเป็นบวก ดังนั้น", "\\frac\\pi4\\left(1-e^{-R^{2}}\\right)\\le I_R^{2}\\le\\frac\\pi4\\left(1-e^{-2R^{2}}\\right)."),
  S("Let $R\\to\\infty$: by the squeeze theorem $I^{2}=\\frac\\pi4$, and $I>0$, so $I=\\frac{\\sqrt\\pi}{2}$. The integrand is even, so $\\int_{-\\infty}^{\\infty}=\\sqrt\\pi$. For $a>0$ substitute $x=\\frac{u}{\\sqrt a}$. $\\blacksquare$", "ให้ $R\\to\\infty$: จากทฤษฎีบทการบีบ $I^{2}=\\frac\\pi4$ และ $I>0$ ดังนั้น $I=\\frac{\\sqrt\\pi}{2}$ ฟังก์ชันเป็นคู่จึง $\\int_{-\\infty}^{\\infty}=\\sqrt\\pi$ สำหรับ $a>0$ แทน $x=\\frac{u}{\\sqrt a}$ $\\blacksquare$")],
 [X(r"\int_{0}^{\infty}e^{-x^{2}}\,dx", "sqrt(pi)/2", r"\frac{\sqrt\pi}{2}", "exp(-x**2)", ("d", "0", "inf"), [r"\text{Half of }\sqrt\pi\text{ (even function)}"]),
  X(r"\int_{0}^{\infty}x^{2}e^{-x^{2}}\,dx", "sqrt(pi)/4", r"\frac{\sqrt\pi}{4}", "x**2*exp(-x**2)", ("d", "0", "inf"), [r"u=x,\ v'=xe^{-x^{2}},\ v=-\tfrac12e^{-x^{2}}", r"\left[-\tfrac x2e^{-x^{2}}\right]_{0}^{\infty}+\tfrac12\int_{0}^{\infty}e^{-x^{2}}dx=0+\tfrac12\cdot\tfrac{\sqrt\pi}{2}=\frac{\sqrt\pi}{4}"])],
 [P(r"\int_{-\infty}^{\infty}e^{-x^{2}}\,dx", "sqrt(pi)", r"\sqrt\pi", "exp(-x**2)", ("d", "-inf", "inf"), [r"\sqrt\pi\ \text{(the theorem)}"], "This is the theorem itself.", "นี่คือทฤษฎีบทโดยตรง"),
  P(r"\int_{0}^{\infty}e^{-4x^{2}}\,dx", "sqrt(pi)/4", r"\frac{\sqrt\pi}{4}", "exp(-4*x**2)", ("d", "0", "inf"), [r"\tfrac12\sqrt{\tfrac\pi4}=\frac{\sqrt\pi}{4}"], "$a=4$, then halve.", "$a=4$ แล้วหารครึ่ง"),
  P(r"\int_{-\infty}^{\infty}e^{-x^{2}+2x}\,dx", "e sqrt(pi)", r"e\sqrt\pi", "exp(-x**2+2*x)", ("d", "-inf", "inf"), [r"-x^{2}+2x=-(x-1)^{2}+1", r"e\int_{-\infty}^{\infty}e^{-(x-1)^{2}}dx=e\sqrt\pi"], "Complete the square in the exponent.", "ทำกำลังสองสมบูรณ์ในเลขชี้กำลัง"),
  P(r"\int_{-\infty}^{\infty}x^{2}e^{-x^{2}}\,dx", "sqrt(pi)/2", r"\frac{\sqrt\pi}{2}", "x**2*exp(-x**2)", ("d", "-inf", "inf"), [r"\text{Even: }2\cdot\frac{\sqrt\pi}{4}=\frac{\sqrt\pi}{2}"], "Use the second example and symmetry.", "ใช้ตัวอย่างที่สองและความสมมาตร"),
  P(r"\int_{0}^{\infty}\frac{e^{-x}}{\sqrt x}\,dx", "sqrt(pi)", r"\sqrt\pi", "exp(-x)/sqrt(x)", ("d", "0", "inf"), [r"x=u^{2},\ dx=2u\,du:\ \int_{0}^{\infty}\frac{e^{-u^{2}}}{u}2u\,du", r"=2\int_{0}^{\infty}e^{-u^{2}}du=\sqrt\pi"], "Let $x=u^{2}$.", "ให้ $x=u^{2}$")]),

L("gamma", "F", "Gamma and Beta functions", "ฟังก์ชันแกมมาและบีตา",
 [T("<b>Definitions.</b> For $s>0$: $\\Gamma(s)=\\displaystyle\\int_{0}^{\\infty}x^{s-1}e^{-x}\\,dx$. For $m,n>0$: $B(m,n)=\\displaystyle\\int_{0}^{1}x^{m-1}(1-x)^{n-1}\\,dx$.", "<b>นิยาม</b> สำหรับ $s>0$: $\\Gamma(s)=\\displaystyle\\int_{0}^{\\infty}x^{s-1}e^{-x}\\,dx$ สำหรับ $m,n>0$: $B(m,n)=\\displaystyle\\int_{0}^{1}x^{m-1}(1-x)^{n-1}\\,dx$"),
  T("<b>Theorem.</b> (i) $\\Gamma(s)$ converges for $s>0$; (ii) $\\Gamma(s+1)=s\\,\\Gamma(s)$, so $\\Gamma(n+1)=n!$; (iii) $\\Gamma\\left(\\tfrac12\\right)=\\sqrt\\pi$; (iv) $$B(m,n)=\\frac{\\Gamma(m)\\Gamma(n)}{\\Gamma(m+n)};$$ (v) $\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta=\\tfrac12B(m,n)$.",
    "<b>ทฤษฎีบท</b> (i) $\\Gamma(s)$ ลู่เข้าเมื่อ $s>0$ (ii) $\\Gamma(s+1)=s\\,\\Gamma(s)$ ดังนั้น $\\Gamma(n+1)=n!$ (iii) $\\Gamma\\left(\\tfrac12\\right)=\\sqrt\\pi$ (iv) $$B(m,n)=\\frac{\\Gamma(m)\\Gamma(n)}{\\Gamma(m+n)}$$ (v) $\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta=\\tfrac12B(m,n)$")],
 [S("(i) On $(0,1]$: $x^{s-1}e^{-x}\\le x^{s-1}$ and $\\int_{0}^{1}x^{s-1}dx$ is finite (it equals $\\frac1s$). On $[1,\\infty)$: $x^{s-1}e^{-x/2}$ is bounded (it tends to $0$), say by $M$, so $x^{s-1}e^{-x}\\le Me^{-x/2}$, which is integrable. Comparison gives convergence.", "(i) บน $(0,1]$: $x^{s-1}e^{-x}\\le x^{s-1}$ และ $\\int_{0}^{1}x^{s-1}dx$ มีค่าจำกัด (เท่ากับ $\\frac1s$) บน $[1,\\infty)$: $x^{s-1}e^{-x/2}$ มีขอบเขต (เข้าใกล้ $0$) เช่นโดย $M$ ดังนั้น $x^{s-1}e^{-x}\\le Me^{-x/2}$ ซึ่งอินทิเกรตได้ จากการเปรียบเทียบจึงลู่เข้า"),
  S("(ii) Parts on $[\\varepsilon,R]$ with $u=x^{s}$, $v'=e^{-x}$, then let $\\varepsilon\\to0$, $R\\to\\infty$ (the boundary terms $\\to0$ as $s>0$):", "(ii) ทีละส่วนบน $[\\varepsilon,R]$ โดย $u=x^{s}$, $v'=e^{-x}$ แล้วให้ $\\varepsilon\\to0$, $R\\to\\infty$ (พจน์ขอบ $\\to0$ เพราะ $s>0$):", "\\Gamma(s+1)=\\Big[-x^{s}e^{-x}\\Big]_{0}^{\\infty}+s\\int_{0}^{\\infty}x^{s-1}e^{-x}dx=s\\,\\Gamma(s)."),
  S("With $\\Gamma(1)=\\int_{0}^{\\infty}e^{-x}dx=1$, induction gives $\\Gamma(n+1)=n!$. (iii) Put $x=u^{2}$: $\\Gamma\\left(\\tfrac12\\right)=\\int_{0}^{\\infty}\\frac{e^{-u^{2}}}{u}2u\\,du=2\\cdot\\frac{\\sqrt\\pi}{2}$ (lesson 25).", "เนื่องจาก $\\Gamma(1)=\\int_{0}^{\\infty}e^{-x}dx=1$ อุปนัยให้ $\\Gamma(n+1)=n!$ (iii) แทน $x=u^{2}$: $\\Gamma\\left(\\tfrac12\\right)=\\int_{0}^{\\infty}\\frac{e^{-u^{2}}}{u}2u\\,du=2\\cdot\\frac{\\sqrt\\pi}{2}$ (บทที่ 25)"),
  S("(iv) The integrand below is non-negative, so by <b>Tonelli's theorem</b> (quoted) we may write the product as a double integral over $(0,\\infty)^{2}$:", "(iv) ฟังก์ชันข้างล่างไม่เป็นลบ จาก<b>ทฤษฎีบทของโทเนลลี</b> (อ้างถึง) เขียนผลคูณเป็นอินทิกรัลสองชั้นบน $(0,\\infty)^{2}$ ได้:", "\\Gamma(m)\\Gamma(n)=\\iint x^{m-1}y^{n-1}e^{-(x+y)}\\,dx\\,dy."),
  S("Change variables $x=uv$, $y=u(1-v)$ with $u\\in(0,\\infty)$, $v\\in(0,1)$: a $C^{1}$ bijection with Jacobian $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=u$ (quoted change-of-variables theorem). Then", "เปลี่ยนตัวแปร $x=uv$, $y=u(1-v)$ โดย $u\\in(0,\\infty)$, $v\\in(0,1)$: เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง มีจาโคเบียน $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=u$ (อ้างทฤษฎีบทการเปลี่ยนตัวแปร) จะได้", "\\Gamma(m)\\Gamma(n)=\\int_{0}^{\\infty}u^{m+n-1}e^{-u}du\\int_{0}^{1}v^{m-1}(1-v)^{n-1}dv=\\Gamma(m+n)\\,B(m,n)."),
  S("(v) Substitute $x=\\sin^{2}\\theta$, $dx=2\\sin\\theta\\cos\\theta\\,d\\theta$ in $B(m,n)$: $x^{m-1}(1-x)^{n-1}dx=2\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta$. $\\blacksquare$", "(v) แทน $x=\\sin^{2}\\theta$, $dx=2\\sin\\theta\\cos\\theta\\,d\\theta$ ใน $B(m,n)$: $x^{m-1}(1-x)^{n-1}dx=2\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta$ $\\blacksquare$")],
 [X(r"\int_{0}^{\infty}x^{5}e^{-x}\,dx", "120", r"120", "x**5*exp(-x)", ("d", "0", "inf"), [r"\Gamma(6)=5!=120"]),
  X(r"\int_{0}^{1}x^{3}(1-x)^{2}\,dx", "1/60", r"\frac{1}{60}", "x**3*(1-x)**2", ("d", "0", "1"), [r"B(4,3)=\frac{\Gamma(4)\Gamma(3)}{\Gamma(7)}=\frac{3!\,2!}{6!}=\frac{12}{720}=\frac{1}{60}"])],
 [P(r"\int_{0}^{\infty}x^{4}e^{-x}\,dx", "24", r"24", "x**4*exp(-x)", ("d", "0", "inf"), [r"\Gamma(5)=4!=24"], "$\\Gamma(n+1)=n!$.", "$\\Gamma(n+1)=n!$"),
  P(r"\int_{0}^{\infty}x^{3}e^{-2x}\,dx", "3/8", r"\frac38", "x**3*exp(-2*x)", ("d", "0", "inf"), [r"u=2x:\ \frac{1}{2^{4}}\int_{0}^{\infty}u^{3}e^{-u}du=\frac{3!}{16}=\frac38"], "Let $u=2x$.", "ให้ $u=2x$"),
  P(r"\int_{0}^{1}x^{2}(1-x)^{3}\,dx", "1/60", r"\frac{1}{60}", "x**2*(1-x)**3", ("d", "0", "1"), [r"B(3,4)=\frac{2!\,3!}{6!}=\frac{1}{60}"], "$m=3$, $n=4$.", "$m=3$, $n=4$"),
  P(r"\int_{0}^{\infty}\sqrt x\,e^{-x}\,dx", "sqrt(pi)/2", r"\frac{\sqrt\pi}{2}", "sqrt(x)*exp(-x)", ("d", "0", "inf"), [r"\Gamma\left(\tfrac32\right)=\tfrac12\Gamma\left(\tfrac12\right)=\frac{\sqrt\pi}{2}"], "$\\Gamma\\left(\\frac32\\right)=\\frac12\\Gamma\\left(\\frac12\\right)$.", "$\\Gamma\\left(\\frac32\\right)=\\frac12\\Gamma\\left(\\frac12\\right)$"),
  P(r"\int_{0}^{\frac\pi2}\sin^{3}\theta\cos^{5}\theta\,d\theta", "1/24", r"\frac{1}{24}", "sin(x)**3*cos(x)**5", ("d", "0", "pi/2"), [r"2m-1=3,\ 2n-1=5:\ m=2,\ n=3", r"\tfrac12B(2,3)=\tfrac12\cdot\frac{1!\,2!}{4!}=\frac{1}{24}"], "Use (v): $2m-1=3$, $2n-1=5$.", "ใช้ (v): $2m-1=3$, $2n-1=5$")]),
]
